// claude_po3w — 23 Model (formerly PO3 Watch, live). Runs on every 1H and 4H candle all session plus NY AM; shows only setups takeable right now.
new Function(localStorage.getItem('claude_core'))();
window.__claudeCore({
  key: 'claude_po3w', title: '23 Model', color: '#c9c9cf', theme: { logo: 'data:image/webp;base64,' }, pos: { top: 70, right: 330 },
  run: async function (e, H) {
    const { etp, etMs, addDays, hhmm, C } = H;
    const today = H.tday(Date.now());
    // ~2 sessions of 1m (4 after a weekend) so it works right from the 18:00 open
    let m1 = await H.bars(e, '1', etMs(addDays(today, -2), 18, 0));
    if (m1.length < 1500) m1 = await H.bars(e, '1', etMs(addDays(today, -4), 18, 0));
    if (m1.length < 30) return { html: 'Not enough 1m data yet.', draws: [] };
    const h1 = await H.bars(e, '60', Date.now() - 6 * 864e5);
    const now = m1.at(-1).t + 60000, day = H.tday(m1.at(-1).t), prev = addDays(day, -1);
    const T = (h, m, d = day) => etMs(d, h, m);
    const m5 = H.agg(m1, 5);
    const allB = h1.filter(x => x.t < m1[0].t).concat(m1);

    // liquidity pools
    const pools = [];
    const addR = (name, r) => { if (r) { pools.push({ name: name + ' High', side: 1, p: r.h, t: r.hT }); pools.push({ name: name + ' Low', side: -1, p: r.l, t: r.lT }); } };
    addR('Asia', H.range(m1, T(20, 0, prev), T(0, 0)));
    addR('London', H.range(m1, T(2, 0), T(5, 0)));
    const pd = H.range(h1, T(0, 0, prev), T(0, 0)); if (pd) { pools.push({ name: 'PDH', side: 1, p: pd.h, t: pd.hT }); pools.push({ name: 'PDL', side: -1, p: pd.l, t: pd.lT }); }
    for (const s of H.swings(h1, 2)) pools.push({ name: '1H Swing ' + (s.side > 0 ? 'High' : 'Low'), side: s.side, p: s.p, t: s.t });
    for (const s of H.swings(m5, 2)) pools.push({ name: '5m Swing ' + (s.side > 0 ? 'High' : 'Low'), side: s.side, p: s.p, t: s.t });
    const o830 = m1.find(x => x.t >= T(8, 30) && x.t < T(8, 31));

    // frames: NY AM (9:30), every 1H candle and every 4H candle of the session (18:00 ET → now). Macro hours 7–11 ET are starred.
    const frames = [{ name: 'NY AM ★', short: 'NY AM', tf: 'NY', start: T(9, 30), sweepEnd: T(10, 10), cisdBy: T(10, 30), end: T(12, 0), prevStart: T(8, 30) }];
    const s0 = T(18, 0, prev), HR = 3600e3, lab = t => { const p = etp(t); return String(Math.floor(p.mins / 60)).padStart(2, '0') + ':00'; };
    for (let t = s0 - 8 * HR; t <= now; t += HR) { const h = Math.floor(etp(t).mins / 60), star = h >= 7 && h <= 11 ? ' ★' : ''; frames.push({ name: lab(t) + ' 1H' + star, short: lab(t), tf: '1H', start: t, sweepEnd: t + 20 * 60000, cisdBy: t + 30 * 60000, end: t + HR, prevStart: t - HR }); }
    for (let t = s0 - 8 * HR; t <= now; t += 4 * HR) frames.push({ name: lab(t) + ' 4H', short: '4H ' + lab(t), tf: '4H', start: t, sweepEnd: t + 80 * 60000, cisdBy: t + 2 * HR, end: t + 4 * HR, prevStart: t - 4 * HR });

    function evalFrame(f) {
      if (now <= f.start) return { f, st: 'upcoming' };
      const si = m1.findIndex(x => x.t >= f.start); if (si < 0) return { f, st: 'upcoming' };
      const O = m1[si].o, prevC = H.range(m1, f.prevStart, f.start);
      const lv = pools.filter(p => p.t < f.start).concat(prevC ? [{ name: 'Prior candle High', side: 1, p: prevC.h }, { name: 'Prior candle Low', side: -1, p: prevC.l }] : []);
      const cands = [];
      for (const dir of [1, -1]) {
        let k = -1;
        for (let j = si; j < m1.length && m1[j].t < f.sweepEnd; j++) if (k < 0 || (dir > 0 ? m1[j].l < m1[k].l : m1[j].h > m1[k].h)) k = j;
        if (k < 0) continue;
        const ext = dir > 0 ? m1[k].l : m1[k].h;
        if (dir > 0 ? ext >= O : ext <= O) continue;
        const swept = lv.filter(p => { if (p.side !== -dir || !(dir > 0 ? ext < p.p && p.p < O : ext > p.p && p.p > O)) return false; const tk = H.takenAt(allB, p.p, -dir, (p.t || 0) + 1); return !tk || tk >= f.start; }).map(p => p.name);
        const cs = H.cisdAt(m1, k, dir, f.cisdBy);
        cands.push({ dir, k, ext, cs, swept: [...new Set(swept)] });
      }
      const ok = cands.filter(c => c.cs).sort((a, b) => a.cs.idx - b.cs.idx)[0];
      if (!ok) return { f, st: now < f.cisdBy ? 'watching' : 'no setup', O, cands };
      const { dir, k, ext, cs } = ok;
      // first FVG after the CISD candle
      let fv = null;
      for (let i = Math.max(2, cs.idx); i < m1.length && m1[i].t < f.end; i++) {
        if (dir > 0 && m1[i - 2].h < m1[i].l) { fv = { top: m1[i].l, bot: m1[i - 2].h, i, t: m1[i - 2].t }; break; }
        if (dir < 0 && m1[i - 2].l > m1[i].h) { fv = { top: m1[i - 2].l, bot: m1[i].h, i, t: m1[i - 2].t }; break; }
      }
      if (!fv) return { f, st: now < f.end ? 'CISD – waiting for FVG' : 'no setup', O, ok };
      const entry = dir > 0 ? fv.top : fv.bot;
      const stop = H.rt(e, dir > 0 ? ext * (1 - 0.0003) : ext * (1 + 0.0003));
      const R = Math.abs(entry - stop);
      const tl = [{ name: f.tf === 'NY' ? '9:30 Open' : f.short + ' Open', p: O }];
      if (o830 && o830.t < f.start) tl.push({ name: '8:30 Open', p: o830.o });
      for (const p of lv) { if (p.side !== dir) continue; const tk = H.takenAt(allB, p.p, dir, (p.t || 0) + 1); if (!tk || tk > cs.t) tl.push(p); }
      const beyond = n => tl.filter(p => dir > 0 ? p.p >= entry + n * R : p.p <= entry - n * R).sort((a, b) => dir * (a.p - b.p))[0];
      const t1 = beyond(1) || { name: '1R', p: entry + dir * R }, t2 = beyond(2) || { name: '2R', p: entry + dir * 2 * R };
      let st = 'pending', fillT = null, tp1 = false;
      for (let j = fv.i + 1; j < m1.length; j++) {
        const x = m1[j];
        if (st === 'pending') {
          if (x.t >= f.end) { st = 'expired'; break; }
          if (dir > 0 ? x.c < ext : x.c > ext) { st = 'invalid'; break; }
          if (dir > 0 ? x.l <= entry : x.h >= entry) { st = 'active'; fillT = x.t; if (dir > 0 ? x.l <= stop : x.h >= stop) { st = 'stopped'; break; } }
        } else {
          if (dir > 0 ? x.l <= stop : x.h >= stop) { st = 'stopped'; break; }
          if (dir > 0 ? x.h >= t1.p : x.l <= t1.p) tp1 = true;
          if (dir > 0 ? x.h >= t2.p : x.l <= t2.p) { st = 'done'; break; }
        }
      }
      if (st === 'pending' && now >= f.end) st = 'expired';
      if ((st === 'pending' || st === 'active') && now - m1[fv.i].t > 3600e3) st = 'cleared (1h old)';   // wipe trades an hour after they were posted
      return { f, st, O, ok, fv, entry, stop, R, t1, t2, tp1, fillT };
    }

    const res = frames.map(evalFrame);
    const draws = [], live = [];
    // same trade found by two frames (e.g. 18:00 1H and 18:00 4H) → show it once
    for (const r of res.filter(r => r.st === 'pending' || r.st === 'active')) { const d = live.find(x => x.ok.dir === r.ok.dir && x.entry === r.entry && x.stop === r.stop); if (d) d.f = { ...d.f, name: d.f.name + ' + ' + r.f.name }; else live.push(r); }
    const RR = r => Math.abs(r.t2.p - r.entry) / r.R;
    // one trade at a time: keep the most profitable (a trade already filled first, then the highest R:R)
    if (live.length > 1) { live.sort((a, b) => (b.st === 'active') - (a.st === 'active') || RR(b) - RR(a)); for (const r of live.slice(1)) r.st = 'passed (lower R:R)'; live.length = 1; }
    for (const r of live) {
      const d = r.ok.dir, col = d > 0 ? C.bull : C.bear, k = r.f.short, id = k + r.f.start;
      draws.push({ k: id + 'fvg', type: 'box', t1: r.fv.t, t2: now, top: r.fv.top, bot: r.fv.bot, col, ext: true, label: '1m ' + H.dirName(d) + ' FVG' });
      draws.push({ k: id + 'cisd', type: 'line', t1: r.ok.cs.sT, t2: r.ok.cs.t + 60000, p: r.ok.cs.lvl, col, style: 2, label: '1m ' + H.dirName(d) + ' CISD' });
      draws.push({ k: id + 'en', type: 'line', t1: r.fv.t, p: r.entry, col: C.entry, w: 2, label: k + ' 23 Model Entry' });
      draws.push({ k: id + 'sl', type: 'line', t1: r.fv.t, p: r.stop, col: C.sl, w: 2, label: k + ' 23 Model SL' });
      draws.push({ k: id + 't1', type: 'line', t1: r.fv.t, p: r.t1.p, col: C.tp, label: k + ' 23 Model TP1' });
      draws.push({ k: id + 't2', type: 'line', t1: r.fv.t, p: r.t2.p, col: C.tp, w: 2, label: k + ' 23 Model TP2' });
    }

    // ---- daily + weekly bias (display only — it never changes how 23 Model finds setups)
    // ICT-style read on each timeframe: 1) last completed candle vs the one before (close beyond = continuation, sweep + close back inside = reversal),
    // 2) higher-timeframe structure, 3) draw on liquidity (which side of the last range is still untouched), 4) price vs the period's open
    const HK = 'claude_23_hist|' + e.sym; let hist = window.__23hist;
    if (!hist || hist.k !== HK || Date.now() - hist.at > 10 * 60000) { hist = window.__23hist = { k: HK, at: Date.now(), b: await H.bars(e, '60', etMs(addDays(today, -70), 18, 0)) }; }
    const hh = hist.b.filter(x => x.t < h1[0].t).concat(h1), last = m1.at(-1).c;
    const wdN = d => new Date(d + 'T12:00:00Z').getUTCDay();
    const sesOf = t => etMs(addDays(H.tday(t), -1), 18, 0), weekOf = t => { const d = H.tday(t); return etMs(addDays(d, -(wdN(d) || 7)), 18, 0); };
    const build = (B, key) => { const out = []; for (const x of B) { const k = key(x.t), c = out.at(-1); if (!c || c.t !== k) out.push({ t: k, o: x.o, h: x.h, l: x.l, c: x.c }); else { c.h = Math.max(c.h, x.h); c.l = Math.min(c.l, x.l); c.c = x.c; } } return out; };
    const dayC = build(hh, sesOf), wkC = build(hh, weekOf), h4 = build(hh, t => { const s0 = sesOf(t); return s0 + Math.floor((t - s0) / 144e5) * 144e5; });
    const trend = B => { const sw = H.swings(B, 2); let hi = null, lo = null, tr = 0; for (let i = 0; i < B.length; i++) { for (const q of sw) if (q.i === i - 2) { if (q.side > 0) hi = q; else lo = q; } if (hi && B[i].c > hi.p) { tr = 1; hi = null; } if (lo && B[i].c < lo.p) { tr = -1; lo = null; } } return tr; };
    const readBias = (C_, curStart, nm, short, trends, openP, openN) => {
      const done = C_.filter(d => d.t < curStart), P1 = done.at(-1), P2 = done.at(-2), why = []; let sc = 0;
      if (P1 && P2) {
        if (P1.c > P2.h) { sc += 2; why.push(['Last ' + nm + ' closed above the prior ' + nm + ' high', 1]); }
        else if (P1.c < P2.l) { sc -= 2; why.push(['Last ' + nm + ' closed below the prior ' + nm + ' low', -1]); }
        else if (P1.h > P2.h && P1.c < P2.h) { sc -= 2; why.push(['Last ' + nm + ' swept the prior high and closed back inside', -1]); }
        else if (P1.l < P2.l && P1.c > P2.l) { sc += 2; why.push(['Last ' + nm + ' swept the prior low and closed back inside', 1]); }
        else why.push(['Inside ' + nm + ' — no candle signal', 0]);
      }
      for (const [lab, tr, w] of trends) if (tr) { sc += tr * w; why.push([lab + ' structure ' + (tr > 0 ? 'bullish' : 'bearish'), tr]); }
      if (P1) {
        const cur = hh.filter(x => x.t >= curStart).concat(m1.filter(x => x.t >= curStart && x.t >= h1.at(-1).t)), hiT = cur.some(x => x.h > P1.h), loT = cur.some(x => x.l < P1.l);
        let dol = null;
        if (hiT && !loT) dol = { dir: -1, n: short + 'L', p: P1.l }; else if (loT && !hiT) dol = { dir: 1, n: short + 'H', p: P1.h };
        else if (!hiT && !loT) dol = Math.abs(P1.h - last) <= Math.abs(last - P1.l) ? { dir: 1, n: short + 'H', p: P1.h } : { dir: -1, n: short + 'L', p: P1.l };
        if (dol) { sc += dol.dir; why.push(['Draw on liquidity: ' + dol.n + ' ' + H.fmt(e, dol.p) + (hiT || loT ? ' (other side already taken)' : ' (closest untaken side)'), dol.dir]); }
        else why.push(['Both ' + short + 'H and ' + short + 'L already taken', 0]);
      }
      if (openP != null) { const d = last > openP ? 1 : -1; sc += d * 0.5; why.push([(d > 0 ? 'Above' : 'Below') + ' the ' + openN + ' ' + H.fmt(e, openP), d]); }
      const bias = sc >= 1 ? 1 : sc <= -1 ? -1 : 0, conf = Math.min(1, Math.abs(sc) / 4.5);
      return { bias, conf, why };
    };
    const curS = sesOf(now - 60000), curW = weekOf(now - 60000), mid = m1.find(x => x.t >= T(0, 0) && x.t < T(0, 1));
    const wOpen = (hh.find(x => x.t >= curW) || {}).o;
    const BD = readBias(dayC, curS, 'day', 'PD', [['4H', trend(h4), 1], ['1H', trend(h1), 0.5]], mid ? mid.o : null, 'midnight open');
    const BW = readBias(wkC, curW, 'week', 'PW', [['Daily', trend(dayC), 1], ['4H', trend(h4), 0.5]], wOpen, 'weekly open');
    const bias = BD.bias;   // the trade card compares against the daily bias
    const biasHtml = B => { const col = B.bias > 0 ? C.bull : B.bias < 0 ? C.bear : '#c8c8d0', ct = B.conf >= 0.66 ? 'High' : B.conf >= 0.33 ? 'Medium' : 'Low';
      return `<div style="display:flex;align-items:baseline;justify-content:space-between;margin:2px 0 4px"><span style="font-size:20px;font-weight:800;letter-spacing:1px;color:${col}">${B.bias > 0 ? 'BULLISH' : B.bias < 0 ? 'BEARISH' : 'NEUTRAL'}</span><span style="color:#c4c4cc;font-size:11px">${ct} confidence</span></div>`
        + `<div style="height:4px;border-radius:2px;background:rgba(255,255,255,.12);overflow:hidden;margin-bottom:6px"><div style="height:100%;width:${Math.round(B.conf * 100)}%;background:${col};border-radius:2px"></div></div>`
        + B.why.map(([t, d]) => `<div style="display:flex;gap:6px;color:#e2e2e8;font-size:11px;line-height:1.55"><span style="color:${d > 0 ? C.bull : d < 0 ? C.bear : '#9a9aa2'}">${d > 0 ? '▲' : d < 0 ? '▼' : '•'}</span><span>${t}</span></div>`).join(''); };
    // Daily / Weekly switch (remembers your choice)
    if (!window.__23seg) { window.__23seg = 1; document.addEventListener('click', ev => { const b = ev.target.closest && ev.target.closest('[data-b23]'); if (!b) return; const v = b.dataset.b23; try { localStorage.setItem('claude_23_bias', v); } catch (x) { } const root = b.closest('.g23'); root.querySelectorAll('[data-b23]').forEach(x => { const on = x.dataset.b23 === v; x.style.background = on ? 'rgba(255,255,255,.22)' : 'transparent'; x.style.color = on ? '#fff' : '#b8b8c0'; }); root.querySelectorAll('[data-b23p]').forEach(x => x.style.display = x.dataset.b23p === v ? '' : 'none'); }, true); }
    let sel = 'D'; try { sel = localStorage.getItem('claude_23_bias') || 'D'; } catch (x) { }
    const segB = (v, t) => `<span data-b23="${v}" style="cursor:pointer;padding:3px 12px;border-radius:10px;font-size:10.5px;font-weight:700;letter-spacing:.6px;${sel === v ? 'background:rgba(255,255,255,.22);color:#fff' : 'background:transparent;color:#b8b8c0'}">${t}</span>`;
    let html = H.card('', `<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:4px"><span style="font-weight:700;font-size:10.5px;letter-spacing:1.4px;text-transform:uppercase;color:#d2d2d8">Bias</span><span style="display:inline-flex;padding:2px;border-radius:12px;background:rgba(0,0,0,.25);border:1px solid rgba(255,255,255,.14)">${segB('D', 'DAILY')}${segB('W', 'WEEKLY')}</span></div>`
      + `<div data-b23p="D" style="display:${sel === 'D' ? '' : 'none'}">${biasHtml(BD)}</div><div data-b23p="W" style="display:${sel === 'W' ? '' : 'none'}">${biasHtml(BW)}</div>`
      + `<div style="color:#9a9aa2;font-size:10px;margin-top:4px">Info only — doesn't change how 23 Model picks trades.</div>`);

    const stCol = { pending: '#e8c46a', active: '#5fe0a1', watching: '#8fb4ff', upcoming: '#6e6e77' };
    if (!live.length) html += H.card('', `<div style="color:#9a9aa4;text-align:center;padding:4px 0">No 23 Model trade takeable right now.</div>`);
    for (const r of live) {
      const d = r.ok.dir, col = d > 0 ? C.bull : C.bear;
      let t = `<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px"><span style="font-size:15px;font-weight:800;color:${col}">${d > 0 ? 'LONG' : 'SHORT'}</span><span style="font-size:10px;padding:2px 8px;border-radius:10px;background:${r.st === 'active' ? 'rgba(95,224,161,.15)' : 'rgba(232,196,106,.14)'};color:${r.st === 'active' ? '#5fe0a1' : '#e8c46a'}">${r.st === 'active' ? 'IN TRADE' : 'WAITING FOR FILL'}</span></div>`;
      t += H.row('Entry', H.fmt(e, r.entry), C.entry) + H.row('Stop', H.fmt(e, r.stop), C.sl);
      t += H.row('TP1 · ' + r.t1.name, H.fmt(e, r.t1.p) + (r.tp1 ? ' ✓' : ''), C.tp) + H.row('TP2 · ' + r.t2.name, H.fmt(e, r.t2.p), C.tp);
      t += H.row('R:R to TP2', (Math.abs(r.t2.p - r.entry) / r.R).toFixed(1) + 'R');
      html += H.card(r.f.name, t);
      // the real confluences this trade was built from
      const pt = (dot, txt, sub) => `<div style="display:flex;gap:7px;padding:3px 0;border-bottom:1px solid rgba(255,255,255,.05)"><span style="color:${dot}">◆</span><div><div style="color:#f2f2f5">${txt}</div>${sub ? `<div style="color:#b4b4bc;font-size:10.5px">${sub}</div>` : ''}</div></div>`;
      let cf = pt('#b9b9c2', r.f.name + ' candle open', 'Range open ' + H.fmt(e, r.O) + (r.f.tf === 'NY' ? ' (9:30)' : ''));
      cf += pt(col, 'Manipulation ' + (d > 0 ? 'below' : 'above') + ' the open', (d > 0 ? 'Low ' : 'High ') + H.fmt(e, r.ok.ext) + ' @ ' + hhmm(m1[r.ok.k].t));
      if (r.ok.swept.length) cf += pt(col, 'Liquidity swept', r.ok.swept.join(' · '));
      cf += pt(col, '1m ' + H.dirName(d) + ' CISD', H.fmt(e, r.ok.cs.lvl) + ' @ ' + hhmm(r.ok.cs.t));
      cf += pt(col, '1m ' + H.dirName(d) + ' FVG (entry)', H.fmt(e, r.fv.bot) + ' – ' + H.fmt(e, r.fv.top));
      cf += pt(C.tp, 'Targets', 'TP1 ' + r.t1.name + ' · TP2 ' + r.t2.name);
      cf += pt(bias === d ? C.bull : bias ? C.bear : '#77777f', bias === d ? 'With the daily bias' : bias ? 'Against the daily bias' : 'Daily bias neutral', '');
      html += H.card('Confluences used', cf);
    }
    // recent frames only (started in the last 4h, plus anything live), newest first
    html += H.card('Frames · every 1H & 4H candle (ET)', res.filter(r => r.st === 'pending' || r.st === 'active' || (r.f.start <= now && now - r.f.start < 4 * 3600e3) || r.f.tf === 'NY').sort((a, b) => b.f.start - a.f.start).map(r => H.row(r.f.name, r.st, stCol[r.st] || '#6e6e77')).join(''));
    return { html, draws };
  }
});
